import type { JoltRecord, Person, Location, ItemTemplateTag, SiteAttributeType } from './';
import type { CompanyFile, ExtendedLocalFile } from './companyFile';
import type { Item } from './item';
import type { ItemType } from './item';
import type { ItemOption } from './itemOption';
import type { ListInstance } from './listInstance';
import type { Tag } from './tag';
export type ItemResult = {
    calculatedScore?: number | null;
    completionTimestamp?: number | null;
    isDisplayed?: boolean | null;
    maxPossibleScore?: number | null;
    siteAttribute?: SiteAttributeType | null;
    type: ItemType;
    update?: {
        completionTimestamp?: number;
        value: ItemResultValue;
    };
} & ItemResultTemplate & ItemResultParentInstance & ItemResultValueOptions & JoltRecord;
/**
 * These are the supported record types for the ListGrid
 */
export type ItemResultRecordType = 'AssetInstanceProperty' | 'ItemResult' | 'WorkOrderInstanceProperty';
export type ItemResultValueOptions = {
    resultAssets?: ListInstance[] | null;
    resultCompanyFiles?: CompanyFile[] | null;
    resultDouble?: number | null;
    resultItemOption?: ItemOption | null;
    resultItemOptions?: ItemOption[] | null;
    resultLocation?: Location | null;
    resultLocationTags?: Tag[] | null;
    resultPerson?: Person | null;
    resultText?: string | null;
    resultTexts?: string[] | null;
    propertyAssets?: ListInstance[] | null;
    propertyCompanyFiles?: CompanyFile[] | null;
    propertyDouble?: number | null;
    propertyItemOption?: ItemOption | null;
    propertyItemOptions?: ItemOption[] | null;
    propertyLocation?: Location | null;
    propertyLocationTags?: Tag[] | null;
    propertyPerson?: string | null;
    propertyText?: string | null;
    propertyTexts?: string[] | null;
};
export type ItemResultTemplate = {
    itemTemplate?: Item;
    templateProperty?: Item;
};
export type ItemResultParentInstance = {
    instance?: Pick<ListInstance, 'id'>;
    listInstance?: Pick<ListInstance, 'id'>;
};
/**
 * These are the possible values for the varying result/property fields
 */
export type ItemResultValue = ItemResultValueMap[keyof ItemResultValueMap] | null;
/**
 * These are the final values that represent the ItemResult/InstanceProperty value
 * e.g. A PERSON type ItemResult/InstanceProperty would return the person's id
 */
export type ItemResultRootValue = string | string[] | number | (string | ExtendedLocalFile)[] | null;
/**
 * These are the keys that represent the possible values for the ItemResult/InstanceProperty
 * null is used for types that don't have a value
 */
export type ItemResultValueKey = keyof ItemResultValueOptions | null;
/** This map helps us know what value to expect an ItemResult/InstanceProperty to have
 * based on its type
 */
export type ItemResultValueMap = {
    [ItemType.ASSETS]: ListInstance[] | null;
    [ItemType.CHECKMARK]: number;
    [ItemType.DATE]: number;
    [ItemType.DATE_TIME]: number;
    [ItemType.EMAIL]: string[];
    [ItemType.FREE_RESPONSE]: string;
    [ItemType.LOCATION]: Location;
    [ItemType.LOCATION_TAGS]: Tag[];
    [ItemType.MULTIPLE_CHOICE]: ItemOption[] | ItemOption;
    [ItemType.NUMBER]: number;
    [ItemType.PERSON]: Person;
    [ItemType.PHOTO]: (CompanyFile | ExtendedLocalFile)[];
    [ItemType.SHORT_ENTRY]: string;
    [ItemType.SIGNATURE]: string;
    [ItemType.STOPWATCH]: number;
    [ItemType.STORE_ID]: string;
    [ItemType.SUBTITLE]: null;
    [ItemType.SUB_LIST]: null;
    [ItemType.TEXT]: null;
    [ItemType.YES_NO]: number;
};
export type SignatureItemParsedValue = {
    mx: number | string;
    my: number | string;
    lx: number | string;
    ly: number | string;
}[];
export type FollowUpActionItemResult = ItemResult & {
    followUpActionMetadata?: {
        triggerItemText: string;
        followUpActionItemText: string;
        triggerItemResponse: string;
        triggerItemTags: ItemTemplateTag[];
    };
};
